import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t_str = next(iterator)
    except StopIteration:
        return
    t = int(t_str)

    output_lines = []

    for case_no in range(1, t + 1):
        try:
            N = int(next(iterator))
            P = int(next(iterator))
            M = int(next(iterator))
        except StopIteration:
            break

        edges = []
        for _ in range(P):
            u = int(next(iterator))
            v = int(next(iterator))
            d = int(next(iterator))
            edges.append((d, u, v))

        queries = []
        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iter(iterator)))
            queries.append((u, v))

        edges.sort()

        parent = list(range(N + 1))
        rank = [0] * (N + 1)

        def find(i):
            path = []
            while parent[i] != i:
                path.append(i)
                i = parent[i]
            for node in path:
                parent[node] = i
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i == root_j:
                return False
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True

        adj = defaultdict(list)
        edges_count = 0

        for d, u, v in edges:
            if union(u, v):
                adj[u].append((v, d))
                adj[v].append((u, d))
                edges_count += 1
                if edges_count == N - 1:
                    break

        dist_cache = {}

        def get_dist(u, v):
            if u == v:
                return 0
            key = (min(u, v), max(u, v))
            if key in dist_cache:
                return dist_cache[key]

            visited = set()
            stack = [(u, 0)]
            result = -1

            while stack:
                curr, d_sum = stack.pop()
                if curr == v:
                    result = d_sum
                    break
                if curr in visited:
                    continue
                visited.add(curr)
                for neighbor, weight in adj[curr]:
                    if neighbor not in visited:
                        stack.append((neighbor, d_sum + weight))

            dist_cache[key] = result
            return result

        output_lines.append(f"Case: {case_no}")
        for u, v in queries:
            res = get_dist(u, v)
            output_lines.append(str(res))

    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == "__main__":
    solve()
